import time
import random
import requests

def fetch_with_backoff(url, max_retries=5, base_delay=1.0):
    attempt = 0
    delay = base_delay
    while attempt < max_retries:
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            return response.json()
        elif response.status_code in {429, 500, 502, 503, 504}:
            attempt += 1
            # Backoff exponencial con variación aleatoria (jitter)
            delay = min(delay * 2, 60.0) + random.uniform(0.1, 1.5)
            print(f'Error {response.status_code}. Reintentando en {delay:.2f}s (intento {attempt}/{max_retries})...')
            time.sleep(delay)
        else:
            # Errores 400, 401, 404 no son transitorios: fallar de inmediato
            response.raise_for_status()
    raise RuntimeError(f'Agotados los {max_retries} reintentos para {url}')
